/**
 * An anchored, non-modal surface for rich content (`design/components/popover.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/popover.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import * as zag from '@zag-js/popover'

import {
  KEEPS_HOLDER,
  MEMBER_PROVIDERS,
  Portal,
  Ref,
  SlotOutlet,
  SlotTemplate,
  Spread,
  agentMember,
  anchorProps,
  derived,
  elementRef,
  lenderHolder,
  mergeParts,
  mountEffect,
  normalizeProps,
  setup,
  syncTriggerAnchor,
  uniqueId,
  useDirection,
  useMachine,
  useMediaQuery,
  useMember,
  watchEffect,
} from '@polymorph/angular'
import { usePresence } from '@polymorph/angular/motion'
import styles from '@polymorph/recipes/overlays/popover.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import triggerAnchor from '@polymorph/recipes/overlays/trigger-anchor.module.css'

export type PopoverAlign = NonNullable<PopoverProps['align']>

export type PopoverSide = NonNullable<PopoverProps['side']>

/** An anchored, non-modal surface for rich content: the inputs it takes, by the React member's prop names. */
export interface PopoverProps {
  align?: 'start' | 'center' | 'end'
  defaultOpen?: boolean
  /**
   * The panel's accessible name; required on purpose.
   */
  label: string
  open?: boolean
  /**
   * `'auto'` stays anchored at every width, because Popover is non-modal by contract and a
   * default must not change that on phones only. `'sheet'` is the app's opt-in: unchanged above
   * `30rem`, and a modal bottom sheet below it (the sheet presentation,
   * `design/components/README.md`), as the spec states.
   */
  presentation?: 'auto' | 'sheet'
  side?: 'bottom' | 'top' | 'right' | 'left'
}

/** An anchored, non-modal surface for rich content. */
@Component({
  selector: 'pm-popover',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  viewProviders: [...KEEPS_HOLDER],
  imports: [Portal, Ref, SlotOutlet, SlotTemplate, Spread],
  // prettier-ignore
  template: `<ng-template pmSlot="trigger" [pmSlotOf]="$"><ng-content select="[slot=trigger]" /></ng-template>
<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<!-- trigger -->
<span
[pmSpread]="e1()"
[pmRef]="anchor"
><ng-container [pmSlotOutlet]="'trigger'" [pmSlotOf]="$" /></span>
<ng-template pmPortal>@if (e2()) {<div
[pmSpread]="e3()"
><!-- panel -->
<div
[pmSpread]="e4()"
[pmRef]="panel"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></div></div>}
@if (e5()) {<div
[attr.class]="e6()"
[attr.data-state]="e7()"
[pmRef]="scrim"
></div>}
@if (e8()) {<div
[attr.class]="e9()"
><div
[pmSpread]="e10()"
[pmRef]="sheetPanel"
><!-- panel -->
<div
[attr.class]="e11()"
data-member="popover"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></div></div></div>}</ng-template>`,
})
export class Popover {
  readonly align = input<Exclude<PopoverProps['align'], undefined>, PopoverProps['align']>(
    'start',
    { transform: (value: PopoverProps['align']) => (value === undefined ? 'start' : value) },
  )
  readonly defaultOpen = input<PopoverProps['defaultOpen']>(undefined)
  /**
   * The panel's accessible name; required on purpose.
   */
  readonly label = input.required<PopoverProps['label']>()
  readonly open = input<PopoverProps['open']>(undefined)
  /**
   * `'auto'` stays anchored at every width, because Popover is non-modal by contract and a
   * default must not change that on phones only. `'sheet'` is the app's opt-in: unchanged above
   * `30rem`, and a modal bottom sheet below it (the sheet presentation,
   * `design/components/README.md`), as the spec states.
   */
  readonly presentation = input<
    Exclude<PopoverProps['presentation'], undefined>,
    PopoverProps['presentation']
  >('auto', {
    transform: (value: PopoverProps['presentation']) => (value === undefined ? 'auto' : value),
  })
  readonly side = input<Exclude<PopoverProps['side'], undefined>, PopoverProps['side']>('bottom', {
    transform: (value: PopoverProps['side']) => (value === undefined ? 'bottom' : value),
  })
  readonly onOpenChange = output<boolean>({ alias: 'openChange' })
  protected readonly $ = useMember({
    events: ['openChange'],
    props: {
      align: () => this.align(),
      defaultOpen: () => this.defaultOpen(),
      label: () => this.label(),
      open: () => this.open(),
      presentation: () => this.presentation(),
      side: () => this.side(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly lender = lenderHolder()
  protected readonly uid = uniqueId()
  protected readonly anchor = elementRef<HTMLElement>()
  protected readonly panel = elementRef<HTMLElement>()
  protected readonly scrim = elementRef<HTMLElement>()
  protected readonly sheetPanel = elementRef<HTMLElement>()
  protected readonly phone = useMediaQuery('phone')
  protected readonly sheeting = derived(() => this.$p.presentation === 'sheet' && this.phone())
  protected readonly documentDirection = useDirection()
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          open: this.$p.open,
          defaultOpen: this.$p.defaultOpen,
          modal: this.sheeting.value,
          positioning: {
            placement:
              this.$p.align === 'center' ? this.$p.side : `${this.$p.side}-${this.$p.align}`,
            offset: { mainAxis: 4 },
          },
          onOpenChange: (details) => {
            this.$.emit(this.onOpenChange, 'onOpenChange', details.open)
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  protected readonly present = setup(() =>
    usePresence(
      () => this.api.value.open && !this.sheeting.value,
      () => this.panel.value,
    ),
  )
  protected readonly sheetPresent = setup(() =>
    usePresence(
      () => this.api.value.open && this.sheeting.value,
      () => this.sheetPanel.value,
      'sheet.panel',
      { sheetSide: 'bottom' },
    ),
  )
  protected readonly scrimPresent = setup(() =>
    usePresence(
      () => this.api.value.open && this.sheeting.value,
      () => this.scrim.value,
      'dialog.scrim',
    ),
  )
  private release3: (() => void) | undefined

  constructor() {
    watchEffect(
      () => this.api.value.open,
      () => this.effect1(),
      true,
    )
    mountEffect(() => this.effect2())
    inject(DestroyRef).onDestroy(() => this.release3?.())
    mountEffect(() => this.effect3())
  }

  protected e1() {
    return mergeParts(anchorProps(this.api.value.getTriggerProps()), {
      class: triggerAnchor.anchor,
    })
  }

  protected e2() {
    return this.present.value()
  }

  protected e3() {
    if (!this.present.value()) return undefined as never
    return mergeParts(this.api.value.getPositionerProps())
  }

  protected e4() {
    if (!this.present.value()) return undefined as never
    return mergeParts(this.api.value.getContentProps(), {
      class: styles.panel,
      style: { '--radix-popover-content-transform-origin': 'var(--transform-origin)' },
      hidden: undefined,
      'aria-labelledby': undefined,
      'aria-describedby': undefined,
      'aria-label': this.$p.label,
      'data-member': 'popover',
    })
  }

  protected e5() {
    return this.scrimPresent.value()
  }

  protected e6() {
    if (!this.scrimPresent.value()) return undefined as never
    return sheet.scrim
  }

  protected e7() {
    if (!this.scrimPresent.value()) return undefined as never
    return this.api.value.open ? 'open' : 'closed'
  }

  protected e8() {
    return this.sheetPresent.value()
  }

  protected e9() {
    if (!this.sheetPresent.value()) return undefined as never
    return sheet.positioner
  }

  protected e10() {
    if (!this.sheetPresent.value()) return undefined as never
    return mergeParts(this.api.value.getContentProps(), {
      class: sheet.panel,
      hidden: undefined,
      'aria-labelledby': undefined,
      'aria-describedby': undefined,
      'aria-label': this.$p.label,
      'data-presentation': 'sheet',
    })
  }

  protected e11() {
    if (!this.sheetPresent.value()) return undefined as never
    return styles.sheetBody
  }

  private effect1(): void {
    syncTriggerAnchor(this.anchor.value, this.api.value.getTriggerProps(), this.api.value.open)
  }

  private effect2(): void {
    void (this.lender && (this.lender.element = () => this.panel.value ?? this.sheetPanel.value))
  }

  private effect3(): void {
    this.release3?.()
    const ran = this.lender
      ? () => {}
      : agentMember({
          member: 'Popover',
          element: () => this.panel.value ?? this.sheetPanel.value,
          state: () => ({ open: this.api.value.open }),
          actions: { close: () => this.api.value.open && this.api.value.setOpen(false) },
        })
    this.release3 = () => {
      ran()
    }
  }
}
